"si compone di trifoglio, avena e loietto. Registra una riga per ciascuna essenza impiegata — anche una sola, se hai usato solo quella.": "ਬਰਸੀਮ/ਤਿਪੱਤੀ, ਜਵੀ ਅਤੇ ਰਾਈ ਘਾਹ ਦਾ ਬਣਦਾ ਹੈ। ਹਰ ਵਰਤੀ ਕਿਸਮ ਲਈ ਇੱਕ ਲਾਈਨ ਦਰਜ ਕਰੋ — ਇੱਕ ਹੀ, ਜੇ ਸਿਰਫ਼ ਉਹੀ ਵਰਤੀ।",
