"🌾 Coltivazione": "🌾 ਖੇਤੀ",
"I campi aziendali: colture, semine, lavorazioni, raccolta, programma, costi, report e storico": "ਫ਼ਾਰਮ ਦੇ ਖੇਤ: ਫ਼ਸਲਾਂ, ਬਿਜਾਈ, ਖੇਤ ਦੇ ਕੰਮ, ਵਾਢੀ, ਯੋਜਨਾ, ਖ਼ਰਚੇ, ਰਿਪੋਰਟ ਅਤੇ ਇਤਿਹਾਸ",
